  function timeOnly(v){return v?String(v).slice(11,16):''}
  function setPreviewTime(i,k,v){const r=state.preview[i];if(!r)return;const isOut=k==='punch_out'||k==='shift2_out';r[k]=v?timestampFromOperational(r.operational_date,v,isOut):'';r.split_shift=!!(r.shift2_in||r.shift2_out);r.review_needed=!r.punch_in||!r.punch_out||(r.split_shift&&(!r.shift2_in||!r.shift2_out));}
