  function setPreviewNote(i,v){if(state.preview[i])state.preview[i].note=v||''}
  async function importDeviceFile(){if(!state.preview.length)return;const bad=state.preview.filter(r=>r.review_needed);if(bad.length&&!confirm(`${bad.length} record(s) still need review. Save anyway?`))return;const f=$('deviceFile').files[0],dates=state.preview.map(x=>x.operational_date).filter(Boolean).sort();try{const d=await rpc('attendance_import_records_v11',{p_token:state.token,p_rows:state.preview,p_file_name:f?.name||'Device report',p_upload_type:$('uploadType').value,p_date_from:dates[0],p_date_to:dates.at(-1)});if(f&&state.deviceFileBase64)await rpc('attendance_archive_upload',{p_token:state.token,p_file_name:f.name,p_mime_type:f.type||'application/vnd.ms-excel',p_file_size:f.size,p_base64:state.deviceFileBase64,p_upload_type:$('uploadType').value,p_date_from:dates[0],p_date_to:dates.at(-1),p_rows_imported:d.imported||0});const reportRows=await deviceReportRowsFromPreview();const summary=deviceReportSummary(reportRows);const period=reportPeriodLabel(dates);await rpc('attendance_save_finalized_report_v10',{p_token:state.token,p_file_name:f?.name||'Device report',p_period_label:period,p_date_from:dates[0],p_date_to:dates.at(-1),p_rows:reportRows,p_summary:summary});toast(`Saved ${d.imported} raw device record(s). Final/admin corrections were preserved.`);await loadFinalizedReportHistory();downloadDevicePDF(reportRows,summary,period);downloadDeviceExcel(reportRows,summary,period);await bootstrap();await loadUploadHistory();$('dashDate').value=dates.at(-1);await loadDashboard()}catch(e){toast(e.message,true)}}
  async function loadUploadHistory(){if(!$('uploadHistoryList'))return;try{const rows=await rpc('attendance_upload_history',{p_token:state.token});$('uploadHistoryList').innerHTML=(rows||[]).map(x=>`<div class="doc-row"><div><strong>${esc(x.file_name)}</strong><div class="small muted">${esc(x.upload_type)} · ${esc(x.date_from||'')} → ${esc(x.date_to||'')} · ${x.rows_imported||0} rows · ${new Date(x.created_at).toLocaleString('en-AE')}</div></div><button class="btn secondary" onclick="GoyaAttendance.downloadUpload('${x.id}')">Download</button></div>`).join('')||'<div class="notice">No saved device files.</div>'}catch(e){toast(e.message,true)}}
  async function downloadUpload(id){try{const d=await rpc('attendance_get_upload',{p_token:state.token,p_id:id});if(!d?.base64)return toast('Original file is not available for this older upload.',true);const bin=atob(d.base64),arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([arr],{type:d.mime_type||'application/octet-stream'}));a.download=d.file_name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){toast(e.message,true)}}
  function reportPeriodLabel(dates){if(!dates?.length)return 'Attendance Report';const first=new Date(`${dates[0]}T12:00:00`),last=new Date(`${dates.at(-1)}T12:00:00`);if(first.getFullYear()===last.getFullYear()&&first.getMonth()===last.getMonth())return first.toLocaleDateString('en-AE',{month:'long',year:'numeric'});return `${formatDate(dates[0])} - ${formatDate(dates.at(-1))}`}
  async function deviceReportRowsFromPreview(){const out=[];for(const p of state.preview){const st=state.staff.find(s=>String(s.name||'').trim().toLowerCase()===String(p.name||'').trim().toLowerCase())||{};const match=matchedShiftForPunch(p.punch_in,p.operational_date);let seg1=0,seg2=0;if(p.punch_in&&p.punch_out){let eff=new Date(p.punch_in);if(match){const sch=new Date(match.scheduled);if(eff<sch)eff=sch}seg1=Math.max(0,Math.round((new Date(p.punch_out)-eff)/60000))}if(p.split_shift&&p.shift2_in&&p.shift2_out)seg2=Math.max(0,Math.round((new Date(p.shift2_out)-new Date(p.shift2_in))/60000));const presence=seg1+seg2,defaultBreak=st.default_break_minutes??state.settings.default_break_minutes??60,breakMin=p.break_taken?defaultBreak:0,net=Math.max(0,presence-breakMin),expected=Math.max(0,(st.expected_presence_minutes??state.settings.default_presence_minutes??540)-defaultBreak),ot=Math.max(0,net-expected),late=match?.late||0;out.push({Date:p.operational_date,Staff:p.name,'Employee Code':p.employee_code||'', 'Working Time':p.split_shift?`${timeText(p.punch_in)} - ${timeText(p.punch_out)} / ${timeText(p.shift2_in)} - ${timeText(p.shift2_out)}`:`${timeText(p.punch_in)} - ${timeText(p.punch_out)}`,'Presence Minutes':presence,'Net Minutes':net,'OT Minutes':ot,'Late Minutes':late,'Break Taken':p.break_taken?'Yes':'No','Status':p.review_needed?'Review Needed':'Complete','Note':p.note||''})}return out}
  function deviceReportSummary(rows){const by={};for(const r of rows){const x=by[r.Staff]||(by[r.Staff]={staff:r.Staff,duty:0,presence:0,net:0,ot:0,lateDays:0,lateMinutes:0,review:0});x.duty++;x.presence+=r['Presence Minutes']||0;x.net+=r['Net Minutes']||0;x.ot+=otBlockMin(r['OT Minutes']||0);if(r['Late Minutes']>0){x.lateDays++;x.lateMinutes+=r['Late Minutes']}if(r.Status!=='Complete')x.review++}return {staff_count:Object.keys(by).length,row_count:rows.length,staff:Object.values(by)}}
  function deviceDetailRows(rows){return rows.map(r=>({'Date':r.Date,'Staff':r.Staff,'Device Code':r['Employee Code']||'','Working Time':r['Working Time'],'Presence':minsText(r['Presence Minutes']),'Net Work':minsText(r['Net Minutes']),'OT / Extra':otText(r['OT Minutes']),'OT Hours':otBlockMin(r['OT Minutes'])/60,'Late Minutes':r['Late Minutes']||0,'Break Taken':r['Break Taken'],'Status':r.Status,'Note':r.Note||''}))}
  function deviceSummaryRows(summary){return (summary.staff||[]).map(x=>({'Staff':x.staff,'Duty Records':x.duty,'Total Presence':minsText(x.presence),'Net Working Hours':minsText(x.net),'OT / Extra':otText(x.ot),'OT Hours':otBlockMin(x.ot)/60,'Late Days':x.lateDays,'Late Minutes':x.lateMinutes,'Review / Missing':x.review}))}
  function downloadDevicePDF(rows,summary,period,name=`Goya_Device_Attendance_${String(period).replace(/[^a-z0-9]+/gi,'_')}.pdf`){if(!window.jspdf?.jsPDF)return toast('PDF library is still loading.',true);const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:'landscape'});doc.setFontSize(18);doc.text('GOYA - Attendance Report',14,16);doc.setFontSize(10);doc.text(`Period: ${period}    Staff: ${summary.staff_count||0}    Records: ${summary.row_count||rows.length}`,14,24);doc.text('Missing punches are flagged for HR review and do not block this report.',14,30);doc.autoTable({startY:36,head:[['Staff','Duty Records','Presence','Net Work','OT','Late Days','Missing / Review']],body:(summary.staff||[]).map(x=>[x.staff,x.duty,minsText(x.presence),minsText(x.net),otText(x.ot),x.lateDays,x.review]),styles:{fontSize:9,cellPadding:3},headStyles:{fillColor:[38,59,52]}});const names=[...new Set(rows.map(r=>r.Staff))].sort((a,b)=>a.localeCompare(b));for(const nameStaff of names){const sr=rows.filter(r=>r.Staff===nameStaff);const ss=(summary.staff||[]).find(x=>x.staff===nameStaff)||{};doc.addPage('a4','landscape');doc.setFontSize(15);doc.text(nameStaff,14,16);doc.setFontSize(10);doc.text(`Period: ${period}    Duty Records: ${ss.duty||sr.length}    Net: ${minsText(ss.net||0)}    Total OT: ${otText(ss.ot||0)}`,14,24);doc.autoTable({startY:30,head:[['Date','Working Time','Net','OT','Late','Break','Status','Note']],body:sr.map(r=>[r.Date,r['Working Time'],minsText(r['Net Minutes']),otText(r['OT Minutes']),r['Late Minutes']?`${r['Late Minutes']} min`:'—',r['Break Taken'],r.Status,r.Note||'']),styles:{fontSize:8,cellPadding:2},headStyles:{fillColor:[38,59,52]},columnStyles:{1:{cellWidth:48},7:{cellWidth:45}}})}doc.save(name)}
  function downloadDeviceExcel(rows,summary,period,name=`Goya_Device_Attendance_${String(period).replace(/[^a-z0-9]+/gi,'_')}.xlsx`,separate=false){const detail=deviceDetailRows(rows),sum=deviceSummaryRows(summary),sheets={'Staff Summary':sum,'All Staff - Daily':detail};if(separate){const used=new Set(Object.keys(sheets).map(x=>x.toLowerCase()));for(const staff of [...new Set(detail.map(x=>x.Staff))]){let n=String(staff||'Staff').replace(/[\\/*?:\[\]]/g,' ').trim().slice(0,31)||'Staff';let base=n,i=2;while(used.has(n.toLowerCase()))n=(base.slice(0,27)+` ${i++}`).slice(0,31);used.add(n.toLowerCase());sheets[n]=detail.filter(x=>x.Staff===staff)}}writeWorkbook(sheets,name)}
  async function exportPreviewPDF(){if(!state.preview.length)return toast('Preview a device file first.',true);const dates=state.preview.map(x=>x.operational_date).filter(Boolean).sort(),rows=await deviceReportRowsFromPreview(),summary=deviceReportSummary(rows),period=reportPeriodLabel(dates);downloadDevicePDF(rows,summary,period)}
  async function exportPreviewExcel(separate=false){if(!state.preview.length)return toast('Preview a device file first.',true);const dates=state.preview.map(x=>x.operational_date).filter(Boolean).sort(),rows=await deviceReportRowsFromPreview(),summary=deviceReportSummary(rows),period=reportPeriodLabel(dates);downloadDeviceExcel(rows,summary,period,`Goya_Device_Attendance_${String(period).replace(/[^a-z0-9]+/gi,'_')}${separate?'_Staff_Sheets':''}.xlsx`,separate)}
  async function loadFinalizedReportHistory(){if(!$('finalizedReportList'))return;try{const rows=await rpc('attendance_finalized_report_history_v10',{p_token:state.token});$('finalizedReportList').innerHTML=(rows||[]).map(x=>`<div class="final-report-row"><div><strong>${esc(x.period_label||x.file_name||'Attendance Report')}</strong><div class="small muted">${esc(x.date_from||'')} → ${esc(x.date_to||'')} · ${x.summary?.staff_count||0} staff · ${new Date(x.created_at).toLocaleString('en-AE')}</div></div><div class="report-actions"><button class="btn secondary" onclick="GoyaAttendance.redownloadFinalizedReport('${x.id}','pdf')">PDF</button><button class="btn secondary" onclick="GoyaAttendance.redownloadFinalizedReport('${x.id}','excel')">Excel All</button><button class="btn secondary" onclick="GoyaAttendance.redownloadFinalizedReport('${x.id}','staffexcel')">Excel Staff Sheets</button><button class="btn success" onclick="GoyaAttendance.regenerateFinalizedReport('${x.id}')">Regenerate Latest</button></div></div>`).join('')||'<div class="notice">No finalized device reports yet.</div>'}catch(e){toast(e.message,true)}}
