  function subInput(id,field,val,disabled=false){return `<input class="sub-edit" type="time" id="sub_${field}_${id}" value="${esc(timeOnly(val))}" ${disabled?'disabled':''}>`}
  function selectedSubmissionIds(){return [...document.querySelectorAll('.sub-check:checked')].map(x=>x.value)}
  function updateSubSelected(){if($('subSelectedCount'))$('subSelectedCount').textContent=`Selected: ${selectedSubmissionIds().length}`}
  function toggleAllSubmissions(on){document.querySelectorAll('.sub-check').forEach(x=>x.checked=on);updateSubSelected()}
  function clockDiff(a,b){if(!a||!b)return null;return Math.round((new Date(a.replace(' ','T'))-new Date(b.replace(' ','T')))/60000)}
  function durationMinutes(a,b){if(!a||!b)return null;let x=new Date(a.replace(' ','T')),y=new Date(b.replace(' ','T'));return Math.max(0,Math.round((y-x)/60000))}
  function staffWorkedMinutes(x){if(x.day_off)return 0;let total=durationMinutes(x.punch_in,x.punch_out);if(total==null)return null;if(x.split_shift){const s2=durationMinutes(x.shift2_in,x.shift2_out);if(s2==null)return null;total+=s2}return total}
  function deviceWorkedMinutes(x){let total=durationMinutes(x.device_punch_in,x.device_punch_out);if(total==null)return null;if(x.device_split_shift){const s2=durationMinutes(x.device_shift2_in,x.device_shift2_out);if(s2==null)return null;total+=s2}return total}
  function signedMinutes(v){if(v==null)return '—';if(v===0)return 'Match';return `${v>0?'+':''}${v} min`}
  function comparisonData(x){const hasDevice=!!(x.device_punch_in||x.device_punch_out||x.device_shift2_in||x.device_shift2_out);if(!hasDevice)return {hasDevice:false,inDiff:null,outDiff:null,splitText:'—',breakText:'—',workDiff:null,otDiff:null,result:'No Device Record',match:false};if(x.day_off)return {hasDevice:true,inDiff:null,outDiff:null,splitText:'—',breakText:'—',workDiff:null,otDiff:null,result:'Mismatch',match:false};const inDiff=clockDiff(x.punch_in,x.device_punch_in),outDiff=clockDiff(x.punch_out,x.device_punch_out);let splitMatch=true,splitText='No';if(x.split_shift||x.device_split_shift){const i2=clockDiff(x.shift2_in,x.device_shift2_in),o2=clockDiff(x.shift2_out,x.device_shift2_out);splitMatch=i2===0&&o2===0&&!!x.split_shift===!!x.device_split_shift;splitText=`In 2: ${signedMinutes(i2)} · Out 2: ${signedMinutes(o2)}`}const breakMatch=!!x.break_taken===!!x.device_break_taken,breakText=breakMatch?'Match':`Staff ${x.break_taken?'Yes':'No'} / Device ${x.device_break_taken?'Yes':'No'}`;const sw=staffWorkedMinutes(x),dw=deviceWorkedMinutes(x),workDiff=sw==null||dw==null?null:sw-dw;const expected=Math.max(0,Number(x.expected_presence_minutes||540)-Number(x.break_minutes||60));const staffNet=sw==null?null:Math.max(0,sw-(x.break_taken?Number(x.break_minutes||60):0)),deviceNet=dw==null?null:Math.max(0,dw-(x.device_break_taken?Number(x.break_minutes||60):0));const sot=staffNet==null?null:otBlockMin(Math.max(0,staffNet-expected)),dot=deviceNet==null?null:otBlockMin(Math.max(0,deviceNet-expected)),otDiff=sot==null||dot==null?null:sot-dot;const match=inDiff===0&&outDiff===0&&splitMatch&&breakMatch&&workDiff===0&&otDiff===0;return {hasDevice:true,inDiff,outDiff,splitText,breakText,workDiff,otDiff,result:match?'Exact Match':'Mismatch',match}}
  function submissionWorkingText(x,device=false){if(!device&&x.day_off)return 'Day Off';const a=device?x.device_punch_in:x.punch_in,b=device?x.device_punch_out:x.punch_out,split=device?x.device_split_shift:x.split_shift,c=device?x.device_shift2_in:x.shift2_in,d=device?x.device_shift2_out:x.shift2_out;if(!a&&!b&&!c&&!d)return 'No device record';let txt=`${timeText(a)} → ${timeText(b)}`;if(split||c||d)txt+=` / ${timeText(c)} → ${timeText(d)}`;return txt}
  function renderSubmissionComparison(){if(!$('submissionRows'))return;const month=$('subMonth')?.value||'',staffId=$('subStaff')?.value||'',mode=$('subMatch')?.value||'';let rows=[...state.submissions];if(month)rows=rows.filter(x=>String(x.operational_date||'').startsWith(month));if(staffId)rows=rows.filter(x=>x.attendance_staff_id===staffId);rows=rows.map(x=>({x,c:comparisonData(x)}));if(mode==='mismatch')rows=rows.filter(v=>v.c.hasDevice&&!v.c.match);if(mode==='match')rows=rows.filter(v=>v.c.match);if(mode==='no_device')rows=rows.filter(v=>!v.c.hasDevice);$('submissionRows').innerHTML=rows.length?rows.map(({x,c})=>`<tr><td><input class="sub-check" type="checkbox" value="${x.id}" onchange="GoyaAttendance.updateSubSelected()"></td><td>${esc(x.operational_date)}</td><td><strong>${esc(x.staff_name)}</strong></td><td><div class="compare-stack">${esc(submissionWorkingText(x,false))}<small>Break: ${x.day_off?'—':(x.break_taken?'Yes':'No')}</small></div></td><td><div class="compare-stack">${esc(submissionWorkingText(x,true))}<small>${c.hasDevice?`Break: ${x.device_break_taken?'Yes':'No'}`:''}</small></div></td><td class="${c.inDiff===0?'diff-ok':'diff-warn'}">${esc(signedMinutes(c.inDiff))}</td><td class="${c.outDiff===0?'diff-ok':'diff-warn'}">${esc(signedMinutes(c.outDiff))}</td><td class="${c.workDiff===0?'diff-ok':'diff-warn'}">${esc(signedMinutes(c.workDiff))}</td><td class="${c.otDiff===0?'diff-ok':'diff-warn'}">${c.otDiff==null?'—':(c.otDiff===0?'Match':`${c.otDiff>0?'+':''}${otText(Math.abs(c.otDiff))}`)}</td><td>${statusPill(c.result)}</td><td><button class="btn success small-btn" onclick="GoyaAttendance.approveSubmission('${x.id}')">Approve</button></td></tr>`).join(''):'<tr><td colspan="11">No comparison records for this filter.</td></tr>';updateSubSelected()}
