  async function generateMonthlySummary(){const m=$('monthPick').value||monthNow();try{const p=await buildPayrollMonth(m);state.monthly=p.summary;state.monthlyDetails=p.details;$('monthlyRows').innerHTML=state.monthly.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.employment_type)}</td><td>${x.duty}</td><td>${x.off}</td><td>${minsText(x.presence)}</td><td>${minsText(x.net)}</td><td>${x.ot?`+${otText(x.ot)}`:'—'}</td><td>${x.late}</td><td>${x.lateMinutes}</td><td>${minsText(x.breakDeduction)}</td><td>${x.missing}</td><td>${x.weekly}</td></tr>`).join('');return p}catch(e){toast(e.message,true);throw e}}
  function payrollSummaryRows(){return state.monthly.map(x=>({'Staff':x.name,'Employment Type':x.employment_type,'Duty Days':x.duty,'Day Off':x.off,'No Record Days':x.noRecord,'Total Presence':minsText(x.presence),'Net Working Hours':minsText(x.net),'OT / Extra Hours':otText(x.ot),'Late Days':x.late,'Late Minutes':x.lateMinutes,'Break Deducted':minsText(x.breakDeduction),'Missing Punch':x.missing,'Longest Duty Streak':x.maxStreak,'Weekly Off Compliance':x.weekly}))}
