  async function exportHRRangeExcel(start,end,name){const rec=await getRange(start,end),staffMap=new Map(state.staff.map(s=>[s.id,s])),sumMap=new Map(),details=[];rec.forEach(r=>{const st=staffMap.get(r.attendance_staff_id)||{name:r.staff_name||'',employment_type:r.employment_type||''};if(!sumMap.has(r.attendance_staff_id))sumMap.set(r.attendance_staff_id,{Staff:st.name||r.staff_name||'','Employment Type':st.employment_type||r.employment_type||'','Duty Days':new Set(),'Total Presence Min':0,'Net Work Min':0,'OT Min':0,'Late Days':0,'Late Minutes':0,'Break Deduct Min':0,'Missing Punch':0});const x=sumMap.get(r.attendance_staff_id);x['Duty Days'].add(r.operational_date);x['Total Presence Min']+=r.presence_minutes||0;x['Net Work Min']+=r.net_work_minutes||0;x['OT Min']+=r.additional_minutes||0;if(r.late_minutes>0){x['Late Days']++;x['Late Minutes']+=r.late_minutes||0}if(r.break_taken)x['Break Deduct Min']+=r.break_minutes||st.default_break_minutes||0;if(recordStatus(r,r.operational_date)==='Missing Punch')x['Missing Punch']++;details.push({'Date':r.operational_date,'Staff':r.staff_name||st.name||'','Employment Type':r.employment_type||st.employment_type||'','Punch In':timeText(r.punch_in),'Punch Out':timeText(r.punch_out),'Presence':minsText(r.presence_minutes||0),'Net Work':minsText(r.net_work_minutes||0),'Break Taken':r.break_taken?'Yes':'No','OT / Extra':otText(r.additional_minutes||0),'Late Minutes':r.late_minutes||0,'Status':recordStatus(r,r.operational_date),'Note':r.note||''})});const summary=[...sumMap.values()].map(x=>({'Staff':x.Staff,'Employment Type':x['Employment Type'],'Duty Days':x['Duty Days'].size,'Total Presence':minsText(x['Total Presence Min']),'Net Working Hours':minsText(x['Net Work Min']),'OT / Extra Hours':otText(x['OT Min']),'Late Days':x['Late Days'],'Late Minutes':x['Late Minutes'],'Break Deducted':minsText(x['Break Deduct Min']),'Missing Punch':x['Missing Punch']}));writeWorkbook({'Staff Summary':summary,'Daily Breakdown':details},name)}
  async function exportManagementPDF(){if(!state.monthly.length)await generateMonthlySummary();if(!window.jspdf?.jsPDF)return toast('PDF library is still loading. Please try again.',true);const m=$('monthPick').value||monthNow(),{jsPDF}=window.jspdf,doc=new jsPDF();doc.setFontSize(18);doc.text('GOYA - Monthly Staff Attendance',14,18);doc.setFontSize(10);doc.text(`Month: ${m}`,14,26);doc.autoTable({startY:32,head:[['Staff','Duty','Off','Net','OT','Late','Missing']],body:state.monthly.map(x=>[x.name,x.duty,x.off,minsText(x.net),otText(x.ot),x.late,x.missing]),styles:{fontSize:8,cellPadding:2},headStyles:{fillColor:[38,59,52]}});const detail=state.monthlyDetails||[];for(const st of state.monthly){doc.addPage();doc.setFontSize(16);doc.text(st.name,14,18);doc.setFontSize(10);doc.text(`Month: ${m}    Duty Days: ${st.duty}    Day Off: ${st.off}    Net: ${minsText(st.net)}    Total OT: ${otText(st.ot)}`,14,27);const rows=detail.filter(x=>x.Staff===st.name&&x.Status!=='No Record').map(x=>[x.Date,x['Working Time'],x.Status==='Day Off'?'—':x['OT / Extra']]);doc.autoTable({startY:34,head:[['Date','Working Time','Overtime']],body:rows,foot:[['','Total Overtime',otText(st.ot)]],styles:{fontSize:10,cellPadding:3},headStyles:{fillColor:[38,59,52]},footStyles:{fontStyle:'bold'}})}doc.save(`Goya_Management_Attendance_${m}.pdf`);toast('Management PDF downloaded')}
  async function finalizeMonthlyPayroll(){const m=$('monthPick').value||monthNow();try{await generateMonthlySummary();const summary=payrollSummaryRows(),details=state.monthlyDetails||[];await rpc('attendance_finalize_month',{p_token:state.token,p_month:`${m}-01`,p_summary:summary,p_details:details});writeWorkbook({'Monthly Summary':summary,'Daily Breakdown':details},`Goya_HR_Final_Attendance_${m}.xlsx`);toast(`Month ${m} finalized and HR Excel downloaded`)}catch(e){toast(e.message,true)}}
  function writeWorkbook(sheets,name){const wb=XLSX.utils.book_new();Object.entries(sheets).forEach(([n,rows])=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),n.slice(0,31)));XLSX.writeFile(wb,name)}

